inline MutationValues Tenant::into_values() && {
    auto r = memory_resource();
    MutationValues values(r);
    values.fields.emplace(String("id", r), generated_detail::encode(r, id_));
    values.fields.emplace(String("name", r), generated_detail::encode(r, name_));
    values.fields.emplace(String("version", r), generated_detail::encode(r, version_));
    detail::EntityRuntimeAccess::retain_loaded_native_values(values, load_state);
    if (auto relation = std::move(entry_list_).into_value()) {
        values.fields.emplace(String("entry_list", r), std::move(*relation));
    }
    inject_runtime(values);
    return values;
}

inline const Tenant* Entry::tenant() const {
    if (tenant_) {
        return tenant_.get();
    }
    if (!is_loaded("tenant")) {
        return nullptr;
    }
    auto* view = root.resolve_relation_option<Tenant>(ENTITY_NAME, id(), "tenant");
    if (view) {
        return *view ? &**view : nullptr;
    }
    return root.resolve_entity<Tenant>(tenantId());
}

